insert into public.lessons (chapter_id, slug, title, position, estimated_minutes, content) select id, 'on-tap-trung-cap', '?n t?p t?ng h?p c?p trung c?p', 1, 60, '{"objectives":["K?t h?p module, class, file v? exception th?nh m?t lu?ng nh?.","Thi?t k? d? li?u c? validation v? ??u ra c? th? ki?m tra."],"theory":["B?i to?n nh?p/xu?t d? li?u c? nhi?u ranh gi?i l?i: file kh?ng t?n t?i, JSON sai c? ph?p, tr??ng thi?u ho?c sai ki?u. M?i ranh gi?i c?n th?ng b?o ph? h?p; kh?ng n?n ?? l?i b? b? qua ?m th?m.","T?ch m? h?nh d? li?u kh?i thao t?c file gi?p code d? ki?m th?. V?i v? d? nh?, h?m nh?n d? li?u ?? parse v? tr? k?t qu?; l?p ch? c?n thi?t khi c? tr?ng th?i v? h?nh vi li?n quan.","M?t CLI ghi ch? c? th? chia th?nh ba ph?n: parse tham s?, nghi?p v? th?m/li?t k?/th?ng k?, v? l?p l?u tr? JSON UTF-8. Khi nhi?u ti?n tr?nh c?ng ghi, file JSON ??n kh?ng cung c?p transaction hay ?i?u ph?i ??ng th?i; ?? l? l?c c?n nh?c database."],"code":"def summarize_tasks(tasks):\n    total = len(tasks)\n    done = sum(task.get(\"done\") is True for task in tasks)\n    return {\"total\": total, \"done\": done, \"remaining\": total - done}\n\nprint(summarize_tasks([{\"done\": True}, {\"done\": False}]))","explanation":"Generator expression t?o c?c gi? tr? bool ???c sum; True ???c t?nh nh? 1. K?t qu? l? dictionary m?i, kh?ng s?a danh s?ch tasks.","output":"{''total'': 2, ''done'': 1, ''remaining'': 1}","mistakes":["D?ng task[\"done\"] khi tr??ng c? th? thi?u m? kh?ng c? validation.","Tr?n ??c file, parse, t?nh to?n v? in trong c?ng m?t h?m l?n."],"summary":["Chia ri?ng ??c/parse, validate, x? l? v? tr?nh b?y.","X? l? d? li?u thi?u c? ch? ??ch.","H?m thu?n d? ki?m th? h?n ph?n ph? thu?c file ho?c m?ng."],"exercises":["??c danh s?ch nhi?m v? t? JSON, ki?m tra ki?u d? li?u r?i xu?t b?o c?o t?ng h?p.","X?y CLI qu?n l? ghi ch? v?i thao t?c th?m, li?t k? v? th?ng k?; t?ch x? l? d? li?u kh?i ??c/ghi file.","Vi?t test cho d? li?u r?ng, thi?u kh?a v? d? li?u b?nh th??ng."]}'::jsonb from public.chapters 