insert into public.chapters (course_id, slug, title, position) select id, 'lap-trinh-lazy', 'Lập trình lazy và tái sử dụng hành vi', 1 from public.courses where slug = 'python-nang-cao' on conflict (course_id, slug) do update set title = excluded.title, position = excluded.position, updated_at = now();
insert into public.lessons (chapter_id, slug, title, position, estimated_minutes, content) select id, 'iterator-generator', 'Iterator và Generator', 1, 45, '{"objectives":["Giải thích iterable, iterator và giao thức next().","Dùng yield để tạo dữ liệu theo nhu cầu."],"theory":["Iterable cung cấp iterator qua iter(). Iterator trả phần tử kế tiếp qua next() và báo StopIteration khi hết. for tự gọi giao thức này. Generator là iterator được tạo từ hàm có yield; trạng thái hàm được giữ giữa các lần next.","Generator expression và generator function tránh tạo toàn bộ kết quả cùng lúc, hữu ích với luồng dữ liệu lớn. Chúng dùng một lần; nếu cần duyệt lại phải tạo generator mới hoặc lưu dữ liệu ở nơi khác. Lazy evaluation cũng làm lỗi phát sinh khi phần tử được tiêu thụ, không nhất thiết lúc tạo generator."],"code":"def even_numbers(limit):\n    number = 0\n    while number <= limit:\n        yield number\n        number += 2\n\nvalues = even_numbers(6)\nprint(next(values))\nprint(list(values))","explanation":"Lần next đầu lấy 0. Generator tiếp tục từ sau yield, rồi list tiêu thụ các giá trị còn lại cho tới StopIteration.","output":"0\n[2, 4, 6]","mistakes":["Mong generator đã tiêu thụ có thể duyệt lại từ đầu.","Tạo list khổng lồ dù chỉ cần xử lý từng phần tử một."],"summary":["Iterator tạo chuỗi phần tử theo giao thức next.","yield giữ trạng thái và tạo generator.","Generator tiết kiệm bộ nhớ nhưng thường chỉ dùng một lần."],"exercises":["Viết generator đọc file từng dòng và chỉ yield các dòng không rỗng.","Tạo pipeline generator lọc số chẵn rồi bình phương mà không tạo list trung gian."]}'::jsonb from public.chapters where course_id = (select id from public.courses where slug = 'python-nang-cao') and slug = 'lap-trinh-lazy' on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position, estimated_minutes = excluded.estimated_minutes, content = excluded.content, updated_at = now();
insert into public.lessons (chapter_id, slug, title, position, estimated_minutes, content) select id, 'decorator', 'Decorator', 2, 45, '{"objectives":["Hiểu decorator là hàm nhận và trả callable.","Bảo toàn metadata và chuyển tiếp tham số đúng cách."],"theory":["Decorator bọc một hàm hoặc class để thêm hành vi mà không sửa trực tiếp phần thân. Cú pháp @decorator tương đương gán tên hàm bằng kết quả decorator. Closure cho phép hàm bọc giữ tham chiếu đến hàm gốc.","Dùng functools.wraps để bảo toàn __name__, docstring và metadata. Wrapper tổng quát thường nhận *args, **kwargs rồi chuyển cho hàm gốc. Thứ tự nhiều decorator có ý nghĩa vì chúng được lồng từ dưới lên."],"code":"from functools import wraps\n\ndef announce(function):\n    @wraps(function)\n    def wrapper(*args, **kwargs):\n        print(f\"Đang chạy {function.__name__}\")\n        return function(*args, **kwargs)\n    return wrapper\n\n@announce\ndef add(left, right):\n    return left + right\n\nprint(add(2, 3))","explanation":"Decorator tạo wrapper, ghi một thông báo rồi trả lại chính kết quả của hàm gốc. wraps giữ metadata của add.","output":"Đang chạy add\n5","mistakes":["Wrapper không return kết quả nên lời gọi mới trả None.","Bỏ wraps khiến công cụ introspection và thông báo lỗi chỉ thấy tên wrapper."],"summary":["Decorator là higher-order function.","Closure giữ hàm được bọc.","Dùng wraps và chuyển tiếp args/kwargs."],"exercises":["Viết decorator đo thời gian chạy bằng time.perf_counter và trả nguyên kết quả.","Thử bọc hàm có tham số keyword-only và kiểm tra __name__/__doc__."]}'::jsonb from public.chapters where course_id = (select id from public.courses where slug = 'python-nang-cao') and slug = 'lap-trinh-lazy' on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position, estimated_minutes = excluded.estimated_minutes, content = excluded.content, updated_at = now();
insert into public.lessons (chapter_id, slug, title, position, estimated_minutes, content) select id, 'context-manager', 'Context Manager', 3, 40, '{"objectives":["Dùng with để đảm bảo cleanup.","Tạo context manager bằng contextlib.contextmanager."],"theory":["Context manager định nghĩa thiết lập và dọn dẹp tài nguyên quanh một khối lệnh. with gọi __enter__, chạy thân khối, rồi luôn gọi __exit__, kể cả khi phát sinh ngoại lệ. File object là context manager phổ biến.","contextlib.contextmanager biến generator thành context manager: mã trước yield là setup, mã sau yield nằm trong finally để dọn dẹp. Nếu cần xử lý hoặc nuốt ngoại lệ, phải làm rõ vì __exit__/context manager có thể thay đổi việc ngoại lệ tiếp tục lan truyền."],"code":"from contextlib import contextmanager\n\n@contextmanager\ndef managed_name(name):\n    print(f\"Mở {name}\")\n    try:\n        yield name\n    finally:\n        print(f\"Đóng {name}\")\n\nwith managed_name(\"tài nguyên\") as resource:\n    print(f\"Dùng {resource}\")","explanation":"finally chạy khi khối with kết thúc bình thường hoặc bằng ngoại lệ, nhờ vậy cleanup không bị bỏ qua.","output":"Mở tài nguyên\nDùng tài nguyên\nĐóng tài nguyên","mistakes":["Đặt cleanup sau yield nhưng không ở try/finally nên ngoại lệ bỏ qua bước dọn dẹp.","Nuốt ngoại lệ trong __exit__ mà không nhận thức rằng caller sẽ tưởng thao tác thành công."],"summary":["with quản lý vòng đời tài nguyên.","Cleanup nên nằm ở vùng bảo đảm chạy.","Không suppress ngoại lệ nếu chưa có lý do nghiệp vụ."],"exercises":["Viết context manager tạm thay đổi working directory rồi khôi phục lại trong finally.","Thử ném ngoại lệ bên trong with và xác nhận cleanup vẫn chạy."]}'::jsonb from public.chapters where course_id = (select id from public.courses where slug = 'python-nang-cao') and slug = 'lap-trinh-lazy' on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position, estimated_minutes = excluded.estimated_minutes, content = excluded.content, updated_at = now();
insert into public.chapters (course_id, slug, title, position) select id, 'du-lieu-va-dich-vu', 'Dữ liệu và dịch vụ bên ngoài', 2 from public.courses where slug = 'python-nang-cao' on conflict (course_id, slug) do update set title = excluded.title, position = excluded.position, updated_at = now();
insert into public.lessons (chapter_id, slug, title, position, estimated_minutes, content) select id, 'xu-ly-du-lieu-nang-cao', 'Xử lý dữ liệu nâng cao', 1, 50, '{"objectives":["Chọn cấu trúc và thuật toán theo kích thước dữ liệu.","Dùng dataclass và key function để mô hình hóa, sắp xếp."],"theory":["Khi dữ liệu lớn, chi phí thuật toán và số lần duyệt quan trọng. Từ điển/set thường hỗ trợ tra cứu trung bình nhanh theo khóa; sắp xếp toàn bộ tốn O(n log n), vì vậy lọc sớm và tránh lặp lồng nhau không cần thiết.","dataclasses.dataclass tự tạo một số phương thức cho lớp dữ liệu. Nó không tự xác thực dữ liệu; validation vẫn phải viết. Với dữ liệu thiếu hoặc không tin cậy, giữ bước parse/validate riêng và cân nhắc streaming để tránh giữ toàn bộ bản ghi trong bộ nhớ."],"code":"from dataclasses import dataclass\n\n@dataclass(frozen=True)\nclass Reading:\n    topic: str\n    minutes: int\n\nreadings = [Reading(\"hàm\", 20), Reading(\"list\", 35)]\nranked = sorted(readings, key=lambda item: item.minutes, reverse=True)\nprint([(item.topic, item.minutes) for item in ranked])","explanation":"dataclass tạo __init__ và biểu diễn hữu ích; frozen=True ngăn gán lại trường sau khi tạo. sorted trả danh sách mới và key xác định tiêu chí sắp xếp.","output":"[(''list'', 35), (''hàm'', 20)]","mistakes":["Cho rằng type annotation tự kiểm tra kiểu lúc runtime.","Sắp xếp trong place khi cần giữ nguyên thứ tự danh sách đầu vào."],"summary":["Đo kích thước dữ liệu và chọn cách xử lý phù hợp.","Dataclass giảm boilerplate nhưng không thay validation.","sorted tạo bản sao; list.sort sửa tại chỗ."],"exercises":["Tính top 5 chủ đề theo tổng thời lượng bằng dictionary rồi sorted.","Đọc dữ liệu theo generator và chỉ giữ thống kê cần thiết."]}'::jsonb from public.chapters where course_id = (select id from public.courses where slug = 'python-nang-cao') and slug = 'du-lieu-va-dich-vu' on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position, estimated_minutes = excluded.estimated_minutes, content = excluded.content, updated_at = now();
insert into public.lessons (chapter_id, slug, title, position, estimated_minutes, content) select id, 'lam-viec-voi-api', 'Làm việc với API', 2, 50, '{"objectives":["Gửi HTTP request, đọc status và parse JSON.","Đặt timeout và xử lý lỗi mạng/HTTP có chủ đích."],"theory":["API HTTP trao đổi request/response. Cần xem status code, header, body và định dạng dữ liệu. urllib.request có sẵn trong Python; urlopen nhận timeout để tránh chờ vô hạn. HTTPError biểu diễn một số phản hồi lỗi HTTP, còn URLError thường phản ánh vấn đề kết nối.","Không giả định response luôn thành công hoặc JSON hợp lệ. Đặt timeout, kiểm tra status/schema và không ghi token bí mật vào mã nguồn/log. Với API có xác thực, lấy credential từ secret store hoặc biến môi trường phía server; tôn trọng rate limit và điều khoản dịch vụ."],"code":"import json\nfrom urllib.request import Request, urlopen\n\nrequest = Request(\n    \"https://api.github.com/repos/python/cpython\",\n    headers={\"User-Agent\": \"Python-Learning-Hub\"},\n)\nwith urlopen(request, timeout=10) as response:\n    repository = json.load(response)\n    print(response.status, repository[\"full_name\"])","explanation":"Request thêm User-Agent, urlopen có timeout và with đóng response. Ví dụ truy cập endpoint công khai; chương trình cần bắt HTTPError/URLError khi chạy trong ứng dụng.","output":"200 python/cpython (kết quả phụ thuộc dịch vụ và thời điểm chạy)","mistakes":["Không đặt timeout nên request có thể chờ rất lâu.","Cho rằng mã 200 bảo đảm payload đúng schema hoặc ghi access token trực tiếp trong tệp Python."],"summary":["HTTP status, header và body là các phần riêng.","Đặt timeout và xử lý lỗi mạng/HTTP.","Giữ bí mật ngoài source code và kiểm tra response trước khi dùng."],"exercises":["Viết hàm lấy dữ liệu JSON từ endpoint công khai, có timeout và chuyển lỗi thành thông báo phù hợp.","Tách bước gọi mạng khỏi bước xử lý payload để có thể kiểm thử mà không cần internet."]}'::jsonb from public.chapters where course_id = (select id from public.courses where slug = 'python-nang-cao') and slug = 'du-lieu-va-dich-vu' on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position, estimated_minutes = excluded.estimated_minutes, content = excluded.content, updated_at = now();
insert into public.chapters (course_id, slug, title, position) select id, 'chat-luong-du-an', 'Tổ chức và kiểm thử dự án', 3 from public.courses where slug = 'python-nang-cao' on conflict (course_id, slug) do update set title = excluded.title, position = excluded.position, updated_at = now();
insert into public.lessons (chapter_id, slug, title, position, estimated_minutes, content) select id, 'to-chuc-du-an', 'Tổ chức dự án Python', 1, 40, '{"objectives":["Sắp xếp source, test và tài nguyên theo trách nhiệm.","Dùng môi trường ảo và điểm vào chương trình có chủ ý."],"theory":["Một dự án nhỏ có thể gồm src/package_name cho mã, tests cho kiểm thử, README cho cách chạy và pyproject.toml cho metadata/cấu hình công cụ. Tên package nên nhất quán và không trùng module chuẩn. Mỗi module cần ranh giới trách nhiệm rõ.","Không nên tạo quá nhiều tầng thư mục khi dự án còn nhỏ. Dependency cần được khai báo để môi trường khác tái tạo. Tách cấu hình theo môi trường và không commit secret; entry point nên gọi hàm main để logic có thể import/test."],"code":"# src/studylog/cli.py\ndef main():\n    print(\"StudyLog sẵn sàng\")\n\nif __name__ == \"__main__\":\n    main()","explanation":"Guard giúp main chỉ chạy khi file được thực thi trực tiếp. Khi import studylog.cli, định nghĩa hàm được nạp nhưng không tự in thông báo.","output":"Khi chạy trực tiếp: StudyLog sẵn sàng","mistakes":["Đặt mọi logic ở cấp module khiến import gây tác dụng phụ.","Commit .env hoặc dependency máy cá nhân mà không ghi lại trong cấu hình dự án."],"summary":["Tổ chức theo trách nhiệm, không theo số lượng thư mục.","Giữ entry point nhỏ và logic có thể import.","Không commit secret; ghi dependency rõ ràng."],"exercises":["Tổ chức ứng dụng quản lý ghi chú thành model, storage và cli.","Viết README có lệnh tạo venv, cài dependency, chạy và kiểm thử."]}'::jsonb from public.chapters where course_id = (select id from public.courses where slug = 'python-nang-cao') and slug = 'chat-luong-du-an' on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position, estimated_minutes = excluded.estimated_minutes, content = excluded.content, updated_at = now();
insert into public.lessons (chapter_id, slug, title, position, estimated_minutes, content) select id, 'kiem-thu-va-toi-uu', 'Kiểm thử và tối ưu code', 2, 50, '{"objectives":["Viết unit test cho hành vi và trường hợp biên.","Đo hiệu năng trước khi tối ưu."],"theory":["Unit test kiểm tra hành vi của đơn vị nhỏ mà không phụ thuộc mạng/file thật nếu có thể. unittest cung cấp TestCase và assertion; tên phương thức bắt đầu bằng test để được phát hiện. Kiểm thử các giá trị bình thường, biên và lỗi kỳ vọng.","Tối ưu bắt đầu bằng phép đo: cProfile cho thời gian theo hàm, timeit cho phép so sánh đoạn nhỏ. Tập trung thuật toán hoặc I/O lớn nhất; giữ test chạy trước/sau thay đổi. Tối ưu quá sớm làm code khó đọc mà không đem lại cải thiện đáng kể."],"code":"import unittest\n\ndef normalize_name(value):\n    return \" \".join(value.split()).title()\n\nclass NormalizeNameTests(unittest.TestCase):\n    def test_collapses_spaces_and_capitalizes(self):\n        self.assertEqual(normalize_name(\"  nguyen   an \"), \"Nguyen An\")\n\nif __name__ == \"__main__\":\n    unittest.main()","explanation":"Test gọi hàm với đầu vào có khoảng trắng thừa và so sánh với kết quả mong đợi. Chạy tệp sẽ báo pass/fail; test này không cần mạng hay database.","output":"Ran 1 test — OK (nội dung chính xác tùy phiên bản unittest)","mistakes":["Test chỉ kiểm tra implementation nội bộ thay vì hành vi người dùng cần.","Tối ưu dựa trên cảm giác mà không đo hoặc bỏ kiểm thử sau refactor."],"summary":["Test đầu vào bình thường, biên và lỗi.","Test độc lập, lặp lại được.","Đo trước khi tối ưu và xác nhận lại bằng test."],"exercises":["Viết test cho chuỗi rỗng, khoảng trắng và tên có dấu tiếng Việt.","Dùng cProfile đo một chương trình xử lý list rồi xác định hàm tốn thời gian nhất."]}'::jsonb from public.chapters where course_id = (select id from public.courses where slug = 'python-nang-cao') and slug = 'chat-luong-du-an' on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position, estimated_minutes = excluded.estimated_minutes, content = excluded.content, updated_at = now();
insert into public.chapters (course_id, slug, title, position) select id, 'du-an-thuc-te', 'Dự án thực tế', 4 from public.courses where slug = 'python-nang-cao' on conflict (course_id, slug) do update set title = excluded.title, position = excluded.position, updated_at = now();
insert into public.lessons (chapter_id, slug, title, position, estimated_minutes, content) select id, 'du-an-thuc-te-python', 'Dự án thực tế: nhật ký học tập dòng lệnh', 1, 75, '{"objectives":["Thiết kế một CLI nhỏ có lưu trữ JSON và kiểm tra dữ liệu.","Kết hợp module, hàm, exception, file, test và tài liệu."],"theory":["Nhật ký học tập cần thao tác thêm mục, liệt kê mục và tổng hợp thời gian. Mô hình một bản ghi nên có ngày, chủ đề, thời lượng và ghi chú; xác thực thời lượng dương và ngày hợp lệ. Dữ liệu phải được lưu bền vững, encoding UTF-8.","Chia ứng dụng thành model/validation, storage và CLI. Storage chịu trách nhiệm lỗi đọc/ghi; logic tổng hợp nhận dữ liệu và trả kết quả. Viết test cho logic không phụ thuộc terminal trước, sau đó mới thêm giao diện dòng lệnh. README cần ghi rõ hạn chế của file JSON khi nhiều tiến trình cùng ghi."],"code":"from datetime import date\n\ndef make_entry(topic, minutes, note=\"\"):\n    topic = topic.strip()\n    if not topic:\n        raise ValueError(\"Chủ đề không được để trống\")\n    if minutes <= 0:\n        raise ValueError(\"Thời lượng phải lớn hơn 0\")\n    return {\"date\": date.today().isoformat(),\n            \"topic\": topic, \"minutes\": minutes, \"note\": note.strip()}\n\nentry = make_entry(\"Generator\", 35, \"Đọc từng phần tử\")\nprint(entry[\"topic\"], entry[\"minutes\"])","explanation":"Hàm tạo bản ghi chuẩn hóa khoảng trắng và từ chối dữ liệu không hợp lệ. Bài tập mở rộng sẽ thêm json.load/dump, argparse và test riêng; đoạn này không tự lưu dữ liệu.","output":"Generator 35","mistakes":["Lưu trực tiếp input chưa kiểm tra và sau đó để dữ liệu sai lan tới báo cáo.","Gộp parse tham số, ghi file và tính tổng vào một hàm khiến lỗi khó khoanh vùng."],"summary":["Mô hình hóa dữ liệu và xác thực tại ranh giới.","Tách giao diện, nghiệp vụ và lưu trữ.","Kiểm thử logic độc lập trước khi nối I/O."],"exercises":["Hoàn thiện CLI với argparse: add, list và summary; lưu JSON UTF-8.","Viết unittest cho validation, dữ liệu rỗng và tổng thời lượng; mô tả cách xử lý file hỏng."]}'::jsonb from public.chapters where course_id = (select id from public.courses where slug = 'python-nang-cao') and slug = 'du-an-thuc-te' on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position, estimated_minutes = excluded.estimated_minutes, content = excluded.content, updated_at = now();
